pub const fn ahri_e(ctx: &Ctx) -> f32 {
    40f32 * (1f32 + 0.02125 * ctx.ability_power + ctx.e_level)
}

pub const fn ahri_rmin(ctx: &Ctx) -> f32 {
    25f32 * (3f32 + 0.014 * ctx.ability_power + 2f32 * (-1f32 + ctx.r_level))
}

pub const fn ahri_rmax(ctx: &Ctx) -> f32 {
    75f32 * (3f32 + 0.014 * ctx.ability_power + 2f32 * (-1f32 + ctx.r_level))
}

