pub const fn rumble_p1(ctx: &Ctx) -> f32 {
    50f32
        + 0.25 * ctx.ability_power
        + 80f32 * (-1f32 + ctx.level) * (0.7025 + 0.0175 * (-1f32 + ctx.level))
            / 17f32
}

